import React from 'react';
import { Box } from '@chakra-ui/react';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';

export type EnvironmentalQualitiesContentProps = {
  /** c_environmentalNotes HTML string sourced from AP21 via SFCC (PRD-009). */
  content: string;
};

/**
 * SFCC-266 — Environmental Qualities tab content for ZimmPdpDrawer.
 * EU storefronts only (en-eu / fr-eu); the gate lives in product-detail/index.tsx.
 * Presentational: receives the AP21-sourced HTML string as a prop — no data-fetching.
 */
export const EnvironmentalQualitiesContent = ({ content }: EnvironmentalQualitiesContentProps) => {
  return (
    <Box
      color="var(--zimm-color-text-default)"
      textStyle="body2"
      sx={{
        // ZimmProductDescription's recipe spaces block children at var(--zimm-scale-l) (20px).
        // Figma specifies var(--zimm-scale-4xl) (64px) between paragraphs for this content.
        // The `& > div > * + *` selector has specificity 0,1,1 vs the recipe's 0,1,0, so it wins.
        '& > div > * + *': {
          marginBlockStart: 'var(--zimm-scale-4xl)',
        },
      }}
    >
      <ZimmProductDescription description={content} />
    </Box>
  );
};

