import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { Box } from '@chakra-ui/react';
import { expect, within } from 'storybook/test';
import { EnvironmentalQualitiesContent } from './environmentalQualitiesContent';

const SAMPLE_CONTENT =
  '<p>Sample environmental text paragraph one.</p>' +
  '<p>More info: <strong>EMBALLAGE</strong></p>';

const meta: Meta<typeof EnvironmentalQualitiesContent> = {
  title: 'Pages/PDP/EnvironmentalQualitiesContent',
  component: EnvironmentalQualitiesContent,
  decorators: [
    (Story: React.ComponentType) => (
      <Box width="522px">
        <Story />
      </Box>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof EnvironmentalQualitiesContent>;

export const Default: Story = {
  name: 'EU environmental qualities — two paragraphs with bold text',
  args: {
    content: SAMPLE_CONTENT,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await expect(canvas.getByText(/Sample environmental text paragraph one/)).toBeInTheDocument();
    await expect(canvas.getByText(/EMBALLAGE/)).toBeInTheDocument();
  },
};
