const testId = document.querySelector('[data-testid="product-description"]');
const parent = testId.parentElement; // should be the Box with the sx selector
const grandparent = parent.parentElement;
const secondChild = testId.children[1];
const rules = [];
for (const sheet of document.styleSheets) {
  let cssRules;
  try { cssRules = sheet.cssRules; } catch(e) { continue; }
  for (const rule of cssRules) {
    try {
      if (rule.selectorText && secondChild.matches(rule.selectorText)) {
        rules.push({selector: rule.selectorText, marginBlockStart: rule.style.marginBlockStart, cssText: rule.style.cssText.slice(0,150)});
      }
    } catch(e) {}
  }
}
JSON.stringify({
  parentTag: parent.tagName,
  parentClass: parent.className,
  grandparentTag: grandparent.tagName,
  grandparentClass: grandparent.className,
  secondChildTag: secondChild.tagName,
  matchedRules: rules,
}, null, 1);

