const nodes = document.querySelectorAll('[data-testid="product-description"]');
const results = [];
nodes.forEach((node, idx) => {
  const box = node.parentElement;
  const children = Array.from(node.children);
  results.push({
    idx,
    textSnippet: node.textContent.slice(0, 60),
    boxClass: box.className,
    childCount: children.length,
    childrenTags: children.map(c => c.tagName),
    childrenMarginTop: children.map(c => getComputedStyle(c).marginBlockStart),
  });
});
JSON.stringify(results, null, 1);

