Author: Jhoan Dela Cruz <jhoan.rose.dela.cruz@accenture.com>
Date:   Wed Sep 16 00:02:17 2026 +0800

    test(pdp): SFCC-266 extract selectEnvQualitiesContent and add unit tests

    Pulls the tab show/fallback logic out of index.tsx into a pure
    selectEnvQualitiesContent function in productInfo.ts (same pattern as
    buildRelatedSwatches — isBlank injected to keep the module dependency-free
    and testable). Replaces the inline showEnvQualitiesTab + envQualitiesContent
    pair with a single call.

    11 new Vitest cases cover: flag-off suppression, AP21 priority, blank-string
    and <p></p> fallback to site pref, both-absent suppression, injected-predicate
    delegation, and AP21-over-fallback ordering.

    Also renames the story title from Pages/PDP/EnvironmentalQualitiesContent to
    Commerce/EnvironmentalQualitiesContent to match the other three PDP partials.

    Co-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>

diff --git a/overrides/app/pages/product-detail/productInfo.test.ts b/overrides/app/pages/product-detail/productInfo.test.ts
index c9565f50..6b554b6c 100644
--- a/overrides/app/pages/product-detail/productInfo.test.ts
+++ b/overrides/app/pages/product-detail/productInfo.test.ts
@@ -9,8 +9,10 @@ import { describe, expect, test, vi } from 'vitest';
 import {
   selectPdpProductInfo,
   buildRelatedSwatches,
+  selectEnvQualitiesContent,
   type PdpSourceProduct,
   type PdpSourcePrice,
+  type PdpProductInfo,
   type RelatedSwatch,
 } from './productInfo';

@@ -226,6 +228,140 @@ describe('selectPdpProductInfo — wasPrice (PRC-09)', () => {
   });
 });

+// ---------------------------------------------------------------------------
+// SFCC-266 — selectEnvQualitiesContent
+// ---------------------------------------------------------------------------
+
+/** Minimal info object for env-qualities tests; only the three relevant fields matter. */
+const envInfo = (
+  over: Partial<Pick<PdpProductInfo, 'showEnvironmentalNote' | 'environmentalNotes' | 'environmentalMessage'>>,
+): PdpProductInfo => ({
+  name: 'Test Product',
+  price: '',
+  showEnvironmentalNote: false,
+  environmentalNotes: undefined,
+  environmentalMessage: undefined,
+  ...over,
+});
+
+/** Treat undefined/null/empty-tag markup as blank; any other string as non-blank. */
+const isBlank = (markup: string | undefined | null) =>
+  markup == null || markup.trim() === '' || markup.replace(/<[^>]*>/g, '').trim() === '';
+
+describe('selectEnvQualitiesContent — tab show/hide and content selection', () => {
+  test('returns undefined when showEnvironmentalNote is false', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({ showEnvironmentalNote: false, environmentalNotes: 'Real AP21 content' }),
+        isBlank,
+      ),
+    ).toBeUndefined();
+  });
+
+  test('returns undefined when showEnvironmentalNote is absent (undefined)', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({ showEnvironmentalNote: undefined, environmentalNotes: 'Real AP21 content' }),
+        isBlank,
+      ),
+    ).toBeUndefined();
+  });
+
+  test('returns undefined when info is null (product still loading)', () => {
+    expect(selectEnvQualitiesContent(null, isBlank)).toBeUndefined();
+  });
+
+  test('returns environmentalNotes when flag is true and notes are non-blank', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({
+          showEnvironmentalNote: true,
+          environmentalNotes: 'Made with recycled fibres',
+          environmentalMessage: 'Fallback message',
+        }),
+        isBlank,
+      ),
+    ).toBe('Made with recycled fibres');
+  });
+
+  test('falls back to environmentalMessage when notes are blank (AC2 — empty string)', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({
+          showEnvironmentalNote: true,
+          environmentalNotes: '',
+          environmentalMessage: 'Site pref fallback',
+        }),
+        isBlank,
+      ),
+    ).toBe('Site pref fallback');
+  });
+
+  test('falls back to environmentalMessage when notes are whitespace-only markup (AC2 — <p></p>)', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({
+          showEnvironmentalNote: true,
+          environmentalNotes: '<p></p>',
+          environmentalMessage: 'Site pref fallback',
+        }),
+        isBlank,
+      ),
+    ).toBe('Site pref fallback');
+  });
+
+  test('falls back to environmentalMessage when notes are undefined', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({ showEnvironmentalNote: true, environmentalNotes: undefined, environmentalMessage: 'Fallback' }),
+        isBlank,
+      ),
+    ).toBe('Fallback');
+  });
+
+  test('returns undefined when both notes and fallback are blank — tab must not appear', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({ showEnvironmentalNote: true, environmentalNotes: '<p> </p>', environmentalMessage: '' }),
+        isBlank,
+      ),
+    ).toBeUndefined();
+  });
+
+  test('returns undefined when both notes and fallback are absent — tab must not appear', () => {
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({ showEnvironmentalNote: true, environmentalNotes: undefined, environmentalMessage: undefined }),
+        isBlank,
+      ),
+    ).toBeUndefined();
+  });
+
+  test('delegates blank-detection to the injected predicate — does not strip tags itself', () => {
+    // A predicate that treats everything as non-blank lets real content through.
+    const neverBlank = () => false;
+    expect(
+      selectEnvQualitiesContent(
+        envInfo({ showEnvironmentalNote: true, environmentalNotes: '<p></p>' }),
+        neverBlank,
+      ),
+    ).toBe('<p></p>');
+  });
+

